-- Volcando datos para la tabla pt06_xavi_rubio.articles: ~6 rows (aproximadamente)
INSERT INTO `articles` (`ID`, `Usuari`, `titol`, `cos`, `qr`) VALUES
	(40, 'j.rubio2@sapalomera.cat', 'Cancelar [Cancel]', '– v. Empezar un movimiento antes de que la animación del previo haya terminado; el final del movimiento previo es “cancelado” y el siguiente inicia inmediatamente. Qué movimientos pueden ser cancelados a otros depende de cada juego, pero en muchos casos ataques débiles pueden ser cancelados a ataques normales, y muchos normales pueden ser cancelados a especiales.', NULL),
	(41, 'j.rubio2@sapalomera.cat', 'Encadenar [Chain]', '– v. Se usa para describir la cancelación de un movimiento a otro.\n– s. El acto de “Encadenar” un movimiento con otro.', NULL),
	(42, 'j.rubio2@sapalomera.cat', 'Daño Chip [Chip Damage]\n', '– s. Ver “Daño por Bloqueo”.\n– v. La acción de causar al oponente este tipo de daño.', NULL),
	(84, 'azaldua@sapalomera.cat', 'Un articulo ejemplar', 'Hola', 'false||true'),
	(92, 'j.rubio2@sapalomera.cat', 'a', 'a', '');

